package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object InvestingCards {
    private val T = Track.INVESTING
    val cards: List<Card> = listOf(
        // ── Level 1: Rookie (tops up the 8 starter cards) ──
        concept("iv-three-buckets", T, 1, "What are the three basic \"asset classes\" most investors start with?",
            "Cash (M-Pesa balance, savings, money market funds): safe, low growth. Bonds (lending to government or companies, e.g. T-bills): steady interest. Shares (owning part of a company, e.g. on the NSE): bumpy but the most growth over long periods."),
        quiz("iv-share-meaning", T, 1, "You buy 100 shares of a company listed on the NSE. You now…",
            listOf("Own a tiny slice of the company", "Have lent the company money", "Are guaranteed a yearly payment", "Work for the company"), 0,
            "A share is part-ownership. You can earn from dividends (a share of profits) and from the price rising, but neither is promised.",
            source = "NSE"),
        quiz("iv-compound", T, 1, "Ksh 10,000 grows 10% a year and you never withdraw. After 2 years you have about…",
            listOf("Ksh 12,000", "Ksh 12,100", "Ksh 11,000", "Ksh 20,000"), 1,
            "Year 1: 11,000. Year 2: 10% of 11,000 = 1,100 more. Earning returns on past returns is compounding, and it snowballs over decades."),
        concept("iv-rule72", T, 1, "What is the \"rule of 72\"?",
            "Divide 72 by the yearly return to estimate how many years it takes to double. At 9% a year: 72 ÷ 9 ≈ 8 years. At 12%: about 6 years. It also works on inflation: at 6% inflation, prices double in about 12 years."),

        // ── Level 2: Hustler ──
        quiz("iv-mmf-wht", T, 2, "A money market fund shows 9.3% a year before tax. Interest has 15% withholding tax. What do you actually keep, roughly?",
            listOf("9.3%", "About 7.9%", "About 6.3%", "About 8.8%"), 1,
            "9.3% × 0.85 ≈ 7.9%. Always compare investments after tax and fees, not on the headline rate.",
            source = "KRA; MMF averages Oct 2026", timeSensitive = true),
        quiz("iv-real-mmf", T, 2, "Your MMF pays about 7.9% after tax and inflation is 6.8%. Your real (buying-power) gain is about…",
            listOf("7.9%", "About 1.1%", "About 14.7%", "Nothing at all"), 1,
            "Real return ≈ after-tax return − inflation: 7.9 − 6.8 ≈ 1.1%. Safe money protects you; it rarely makes you rich.",
            source = "KNBS CPI, Sept 2026", timeSensitive = true),
        concept("iv-time-in-market", T, 2, "Why do long-term investors say \"time in the market beats timing the market\"?",
            "Nobody reliably predicts the next crash or rally. Some of the best days come right after the worst, so people who jump out often miss the rebound. Staying invested through the bumps is how most long-run returns are earned."),
        quiz("iv-fee-drag", T, 2, "Ksh 1M invested for 30 years: Fund A nets 10% a year, Fund B the same but 2% fees (8%). The gap at the end is about…",
            listOf("Ksh 200,000", "Ksh 1M", "Ksh 7.4M", "Ksh 17M"), 2,
            "A grows to about Ksh 17.4M, B to about Ksh 10.1M. A \"small\" 2% yearly fee took around 40% of the final pot.",
            tryThis = "Look up the yearly management fee of any fund you hold."),
        quiz("iv-dca-math", T, 2, "You invest Ksh 5,000 a month. Price is Ksh 50 in month 1 and Ksh 25 in month 2. Your average cost per unit is…",
            listOf("Ksh 37.50", "About Ksh 33.33", "Ksh 25", "Ksh 50"), 1,
            "You bought 100 units, then 200 units: 300 units for Ksh 10,000 = Ksh 33.33 each. Steady buying gets more units when prices are low."),
        quiz("iv-tbill", T, 2, "A Kenyan Treasury bill is…",
            listOf("A short loan to the government, up to 1 year", "A share in the Central Bank", "A 20-year government bond", "An M-Pesa savings product"), 0,
            "T-bills come in 91, 182 and 364 days. You lend to the government and get back the face value; the discount is your interest.",
            source = "CBK"),
        quiz("iv-tbill-rate", T, 2, "In mid-October 2026, roughly what did the 364-day Kenyan T-bill pay a year?",
            listOf("About 4%", "About 9%", "About 16%", "About 25%"), 1,
            "The 15 Oct 2026 auction cleared at about 9.04% for 364 days and 8.75% for 91 days. Rates change every week.",
            source = "CBK auction results, Oct 2026", timeSensitive = true),
        concept("iv-dhowcsd", T, 2, "How can an ordinary Kenyan buy T-bills and bonds directly, without a bank?",
            "Through the CBK's DhowCSD platform (web or app): open a CDS account, bid at the weekly auction and pay from your bank. Interest is paid to your bank account.",
            source = "CBK", tryThis = "Look up DhowCSD on the CBK website.", timeSensitive = true),
        quiz("iv-emergency-first", T, 2, "You have Ksh 40,000 saved, no emergency fund and want to buy shares. The sound order is…",
            listOf("All into shares now", "Build an emergency fund first, then invest", "Borrow to buy more shares", "Wait for a crash first"), 1,
            "Without a buffer, the first car repair forces you to sell shares, possibly at a loss. Safety first, then growth.",
            signals = setOf(Signal.NO_EMERGENCY_FUND)),
        concept("iv-volatility", T, 2, "Shares can fall 30% in a year. Why do people still hold them for long goals?",
            "Over long periods, the swings average out and growth wins. Since 1900, world shares beat inflation by about 5.2% a year, bonds by about 1.7%, and short-term bills by about 0.5%. The bumps are the price of that extra return.",
            source = "UBS Global Investment Returns Yearbook, 2025"),
        you("iv-you-fees", T, 2, "You paid about {fees_year} in fees this year. If you had invested that instead at 10% a year, it would roughly double in 7 years.",
            "Cutting fees is a guaranteed return. Every shilling not lost to charges can start compounding for you.",
            tryThis = "See where your fees came from.", action = Action.PATTERNS, signals = setOf(Signal.HIGH_FEES)),

        // ── Level 3: Pro ──
        quiz("iv-etf-nse", T, 3, "Which ETF on the NSE lets you own big companies across about 23 developed markets, priced in Ksh?",
            listOf("Satrix MSCI World Feeder ETF", "NewGold ETF", "Safaricom PLC", "M-Akiba"), 0,
            "Satrix's MSCI World Feeder ETF listed on the NSE in July 2025 (total expense ratio about 0.35% a year). NewGold tracks gold, not companies.",
            source = "NSE; Satrix, 2025", timeSensitive = true),
        concept("iv-etf-vs-unit", T, 3, "How is an ETF different from a unit trust (like most Kenyan MMFs)?",
            "An ETF trades on a stock exchange all day like a share, through a stockbroker. A unit trust is bought and sold directly from the fund manager at the day's price. ETFs that track an index usually charge lower fees.",
            source = "CMA"),
        quiz("iv-pe", T, 3, "A share costs Ksh 20 and the company earned Ksh 2.50 per share last year. Its P/E ratio is…",
            listOf("8", "12.5", "2.5", "50"), 0,
            "P/E = price ÷ earnings per share = 20 ÷ 2.5 = 8. You pay Ksh 8 for each Ksh 1 of yearly profit. Lower can mean cheap, or that the market expects trouble."),
        quiz("iv-div-yield", T, 3, "A Ksh 20 share pays a Ksh 1.50 dividend. Its dividend yield is…",
            listOf("1.5%", "7.5%", "13.3%", "30%"), 1,
            "Yield = dividend ÷ price = 1.5 ÷ 20 = 7.5%. For Kenyan residents, a 5% withholding tax is usually taken first, leaving about 7.1%.",
            source = "KRA; PwC tax summaries, 2026", timeSensitive = true),
        quiz("iv-yield-trap", T, 3, "A share's dividend yield jumps to 15% because its price crashed. The careful reading is…",
            listOf("A bargain, buy now", "The market may expect the dividend to be cut", "Yields can't change", "The company is growing fast"), 1,
            "Yield rises when price falls. A very high yield often means investors doubt the payout will last. Check profits and debt before trusting it."),
        quiz("iv-bond-price", T, 3, "You hold a bond paying 12% a year. New bonds now pay 14%. What happens to your bond's market price?",
            listOf("It rises", "It falls", "It stays the same", "It doubles"), 1,
            "Nobody pays full price for 12% when 14% is on offer, so your bond's price drops until its yield matches. Rates up, bond prices down."),
        quiz("iv-bond-price-num", T, 3, "A 10-year bond paying 12% is priced at 100. If market yields rise to 14%, its price falls to about…",
            listOf("98", "90", "75", "86"), 1,
            "Discounting its 12% coupons and the 100 repayment at 14% gives about 89.6. A 2-point rate rise cost about 10% of the value.",
            source = "Standard bond pricing"),
        concept("iv-ifb", T, 3, "Why do Kenyan infrastructure bonds (IFBs) often attract retail investors?",
            "Their interest is tax-free under the Income Tax Act, while most other government bond interest has withholding tax. So a 14% IFB can beat a slightly higher-coupon taxable bond. Compare after-tax yields.",
            source = "CBK bond prospectuses", timeSensitive = true),
        quiz("iv-allocation", T, 3, "Which mostly decides how bumpy your portfolio's ride will be?",
            listOf("Which single stock you pick", "Your mix of shares, bonds and cash", "The day of the week you buy", "Your broker's app"), 1,
            "Asset allocation (the mix) drives most of the ups and downs. A 90% shares portfolio swings far more than a 40% one."),
        quiz("iv-rebalance", T, 3, "Target 60% shares / 40% bonds on Ksh 1M. Shares rise 30%, bonds 5%. To rebalance, move about…",
            listOf("Ksh 60,000 from shares to bonds", "Ksh 60,000 from bonds to shares", "Ksh 180,000 from shares to bonds", "Nothing"), 0,
            "Shares grow to 780k, bonds to 420k: total 1.2M. 60% is 720k, so sell 60k of shares and buy bonds. Rebalancing quietly sells high and buys low."),
        quiz("iv-fx-risk", T, 3, "You buy a US fund at Ksh 130 per dollar. It gains 7% in dollars and the shilling weakens to 140. Your Ksh return is about…",
            listOf("7%", "15%", "−1%", "22%"), 1,
            "1.07 × 140/130 ≈ 1.152, so about +15%. A weaker shilling helps foreign assets; a stronger one hurts. Currency is its own risk and return."),
        concept("iv-fx-history", T, 3, "Why do some Kenyans hold part of their long-term money in foreign assets?",
            "The shilling has swung a lot: it weakened to about Ksh 160 per US dollar in January 2024, then recovered to around 129 later that year. Owning some foreign assets spreads the risk of your whole life being priced in one currency.",
            source = "CBK rates via Business Daily, 2024", timeSensitive = true),
        quiz("iv-liquidity", T, 3, "Kenya Airways shares were suspended from NSE trading from July 2020 until January 2025. This shows…",
            listOf("Liquidity risk: you may not be able to sell", "Shares never lose value", "Suspensions protect returns", "Inflation risk"), 0,
            "About 75,000 retail holders couldn't sell for over four years. Diversifying across many companies limits the damage of any one.",
            source = "NSE; Semafor, Jan 2025"),

        // ── Level 4: Shark ──
        concept("iv-duration", T, 4, "What is a bond's \"duration\", and why do pros watch it?",
            "Duration is roughly the % a bond's price moves for a 1-point change in yields. Duration 5.6 means a 1% rate rise cuts the price about 5.6%. Longer bonds and lower coupons have higher duration, so more rate risk."),
        quiz("iv-duration-use", T, 4, "A bond fund has a duration of 6. Yields rise 2 points. Roughly what happens to its price?",
            listOf("Falls about 2%", "Falls about 12%", "Rises about 12%", "Falls about 6%"), 1,
            "Price change ≈ −duration × yield change = −6 × 2 = −12%. Short-duration funds feel rate moves much less."),
        concept("iv-dcf", T, 4, "What is a discounted cash flow (DCF) valuation, in one breath?",
            "A business is worth all the cash it will produce in future, with each future shilling shrunk (discounted) because money later is worth less than money now. Value = sum of future cash ÷ (1 + required return)^years."),
        quiz("iv-gordon", T, 4, "A company pays Ksh 10 a year, growing 5% forever. You need 15% a year. Using the Gordon growth model, it's worth about…",
            listOf("Ksh 67", "Ksh 100", "Ksh 200", "Ksh 50"), 1,
            "Value = next dividend ÷ (required return − growth) = 10 ÷ (0.15 − 0.05) = Ksh 100. Small changes in growth or rate swing the answer hugely.",
            source = "Gordon, 1959"),
        quiz("iv-spiva", T, 4, "Over 15 years, roughly what share of active US large-cap funds trail the S&P 500 index (SPIVA)?",
            listOf("About 25%", "About 50%", "About 90%", "About 10%"), 2,
            "S&P's SPIVA scorecards find around 9 in 10 active large-cap funds lag over 15 years, mostly due to fees. In 2025 alone, 79% lagged.",
            source = "S&P Dow Jones Indices, SPIVA 2025", timeSensitive = true),
        concept("iv-behavior-gap", T, 4, "What is the \"behaviour gap\"?",
            "Investors often earn less than the funds they own because they buy after rises and sell after falls. Morningstar found US investors earned about 1.2% a year less than their funds over the decade to 2025.",
            source = "Morningstar, Mind the Gap 2025"),
        quiz("iv-crypto-law", T, 4, "Since November 2025, who licenses crypto (virtual asset) service providers in Kenya?",
            listOf("CBK and CMA", "KRA only", "Nobody, it's banned", "The NSE"), 0,
            "The Virtual Asset Service Providers Act 2025 makes CBK and CMA the regulators. Licensing starts only once regulations are issued, so check before trusting a platform.",
            source = "CBK public notice, VASP Act 2025", timeSensitive = true),
        concept("iv-crypto-risk", T, 4, "Bitcoin is volatile, but what is the bigger danger most Kenyans face with crypto?",
            "Scams around it: fake platforms, \"trading bots\" and recruiters promising daily returns. Real crypto can drop 50%+, but a fake app can take 100%. Limit any crypto to money you can lose, and never pay to \"unlock\" withdrawals."),
        quiz("iv-forex-signals", T, 4, "Someone sells \"forex signals\" with a guaranteed 20% monthly return and a mentorship fee. The most likely truth is…",
            listOf("A secret edge", "Their income comes from your fees, not trading", "A licensed fund manager", "Low-risk arbitrage"), 1,
            "Most retail forex traders lose money. Anyone offering guaranteed returns is selling hope. Check the CMA's list of licensed brokers first.",
            source = "CMA investor alerts", tryThis = "Search the CMA website for its list of licensed forex brokers."),
        quiz("iv-cytonn", T, 4, "Cytonn High Yield Solutions promised up to 18% a year and defaulted. A key warning sign was…",
            listOf("It was a CMA-regulated MMF", "It was sold as an unregulated private placement", "It was listed on the NSE", "It paid low returns"), 1,
            "It wasn't a CMA-regulated product; about Ksh 13.5B in it and project notes ran into trouble. High promised returns plus no regulator is a red flag.",
            source = "Business Daily; Nation, 2021"),
        concept("iv-sequence", T, 4, "What is \"sequence risk\" for an investor?",
            "The same average return can end very differently depending on when the bad years hit. A crash right before or after you start withdrawing hurts far more than one 20 years earlier, because you sell more units at low prices."),
        concept("iv-emh", T, 4, "What does the \"efficient market hypothesis\" claim?",
            "Prices quickly reflect public information, so it's very hard to beat the market consistently after costs. Eugene Fama set it out in 1970. Markets aren't perfect, but beating them reliably is rare.",
            source = "Fama, 1970"),
        quiz("iv-leverage", T, 4, "You borrow to double your investment (2x leverage). The market falls 25%. Your own money falls about…",
            listOf("25%", "50%", "12.5%", "75%"), 1,
            "Leverage multiplies losses as well as gains: 2 × 25% = 50%, before interest costs. A 50% market fall at 2x wipes you out."),

        // ── Level 5: Legend ──
        concept("iv-markowitz", T, 5, "What did Harry Markowitz show in \"Portfolio Selection\" (1952)?",
            "Judge an investment by how it changes the whole portfolio's risk and return, not on its own. Mixing assets that don't move together can lower risk without lowering return. It earned him a Nobel Prize in 1990.",
            source = "Markowitz, Journal of Finance, 1952"),
        quiz("iv-fama-french", T, 5, "Fama and French's three-factor model (1993) explains stock returns using the market plus…",
            listOf("Size and value", "Momentum and gold", "Dividends and debt", "Interest rates and oil"), 0,
            "Small companies and cheap (\"value\") stocks earned extra returns historically. In 2015 they added profitability and investment for a five-factor model.",
            source = "Fama & French, 1993; 2015"),
        quiz("iv-sharpe-arith", T, 5, "William Sharpe's \"Arithmetic of Active Management\" (1991) argues that, on average, active investors…",
            listOf("Beat the market", "Must trail passive investors after costs", "Match the market exactly", "Avoid all losses"), 1,
            "Together, active investors own the market, so before costs they earn the market average. After their higher costs, they must lag on average.",
            source = "Sharpe, 1991"),
        concept("iv-bogle", T, 5, "What was \"Bogle's folly\", and what is the \"cost matters hypothesis\"?",
            "John Bogle's Vanguard launched the first index fund for ordinary investors in 1976; critics mocked it. His cost matters hypothesis: since the market's gross return is shared, the investors paying the least keep the most.",
            source = "Bogle, Vanguard history"),
        quiz("iv-buffett-bet", T, 5, "In Buffett's 10-year bet (2008–2017), an S&P 500 index fund gained about 126%. Five hedge-fund portfolios averaged about…",
            listOf("36%", "150%", "126%", "90%"), 0,
            "The index fund made about 8.5% a year; the funds of funds averaged about 36% in total after fees. High fees ate the professionals' edge.",
            source = "Buffett, Berkshire letter 2017"),
        quiz("iv-barber-odean", T, 5, "Barber and Odean (2000) studied 66,000 US households. The ones who traded most…",
            listOf("Earned the most", "Earned noticeably less", "Matched the market", "Avoided crashes"), 1,
            "Their paper \"Trading Is Hazardous to Your Wealth\" found the most active traders earned about 11.4% a year vs 17.9% for the market, mainly due to costs.",
            source = "Barber & Odean, Journal of Finance, 2000"),
        concept("iv-bessembinder", T, 5, "What did Hendrik Bessembinder find in \"Do Stocks Outperform Treasury Bills?\" (2018)?",
            "Most individual US stocks since 1926 did worse than T-bills over their lifetimes. About 4% of companies created all the net wealth. Picking a few stocks risks missing the rare winners; owning the whole market catches them.",
            source = "Bessembinder, Journal of Financial Economics, 2018"),
        quiz("iv-dms", T, 5, "Dimson, Marsh and Staunton's data (35 markets, 1900–2024) put world shares' real return at about…",
            listOf("1.7% a year", "5.2% a year", "10% a year", "0.5% a year"), 1,
            "About 5.2% a year above inflation for shares, 1.7% for bonds and 0.5% for bills. The 25 years to 2024 earned less: about 3.5% real.",
            source = "UBS Global Investment Returns Yearbook, 2025"),
        concept("iv-survivorship", T, 5, "Why might long-run stock data be too rosy (survivorship bias)?",
            "We study markets that survived. Russian investors lost almost everything after 1917, Chinese investors after 1949. Long, unbroken data series come mostly from success stories like the US, so global diversification is a hedge against picking the next failure."),
        quiz("iv-mr-market", T, 5, "Benjamin Graham's \"Mr. Market\" (The Intelligent Investor) teaches that market prices…",
            listOf("Are always right", "Are moody offers you can take or ignore", "Predict the economy", "Should be followed daily"), 1,
            "Mr. Market offers to buy or sell every day, sometimes euphoric, sometimes depressed. You're free to ignore him and use his mood when it suits you.",
            source = "Graham, The Intelligent Investor, 1949"),
        concept("iv-tulips", T, 5, "What happened in the Dutch \"tulip mania\" of 1636–37?",
            "Prices for rare tulip bulbs soared in futures-style contracts, then collapsed in early 1637. Historians debate how widespread the damage was, but it became the classic tale of a price driven by the hope of selling to someone else.",
            source = "Garber, Famous First Bubbles, 2000"),
        quiz("iv-dotcom", T, 5, "After peaking in March 2000, the tech-heavy Nasdaq fell by about how much before bottoming in 2002?",
            listOf("20%", "45%", "78%", "95%"), 2,
            "It lost about 78% and took about 15 years to regain its 2000 peak. Exciting new technology doesn't guarantee good returns if you overpay.",
            source = "Nasdaq Composite history"),
        quiz("iv-japan", T, 5, "Japan's Nikkei 225 peaked in December 1989. When did it finally beat that peak?",
            listOf("1995", "2007", "2024", "It never has"), 2,
            "It took over 34 years, until February 2024. A whole national market can stay down for decades, another case for spreading across countries.",
            source = "Nikkei 225 history"),
        concept("iv-2008", T, 5, "What drove the 2008 crash, and how far did US shares fall?",
            "Banks had borrowed heavily against risky US mortgage loans; when home prices fell, losses spread through the financial system. The S&P 500 fell about 57% from October 2007 to March 2009, then recovered over the following years.",
            source = "S&P 500 history"),
        concept("iv-grossman-stiglitz", T, 5, "What is the Grossman–Stiglitz paradox (1980)?",
            "If markets were perfectly efficient, nobody would be paid to research, so nobody would, and prices would stop being efficient. So markets stay \"nearly\" efficient: research earns just enough to cover its cost, leaving little for others.",
            source = "Grossman & Stiglitz, American Economic Review, 1980"),
    )
}
